package lint

import (
	"fmt"
	"path"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

// The generated rule: every file a program writes says so, naming its
// generator and its source, and the checkout's generated.yaml declares it
// (SE's guidance note generated-files-are-marked owns the rule, its wording
// and its regular expressions; SE's scripts/generated.py holds the same
// reading). Beside its errors the rule makes one notice on each generated
// file, what the editor shows on it: `generated by <generator> from
// <source>; edit <source>`.

// RuleGenerated is a generated file without its marker, a marked file no
// declaration covers, a declaration that matches nothing, and the notice on
// each generated file.
const RuleGenerated = "generated"

// The files the rule reads beside the one it judges, at the checkout's root.
const (
	// Declarations lists each generator, its source, the paths it writes and
	// how a fresh run is compared.
	Declarations = "generated.yaml"
	// Attributes marks a generated file in a format without comments.
	Attributes = ".gitattributes"
)

// The .gitattributes attributes that mark a file generated.
const (
	linguist  = "linguist-generated"
	attribute = "generated-by"
)

// Syntax is a comment syntax a marker is written in: what opens a comment
// line and what closes it.
type Syntax struct{ Open, Close string }

// The comment syntaxes a marker is written in.
var (
	Hash  = Syntax{"# ", ""}
	Slash = Syntax{"// ", ""}
	HTML  = Syntax{"<!-- ", " -->"}
)

// extensions are the comment syntax of each extension; a file with none but
// a `#!` line is Hash. Every other format has none the rule knows, and
// .gitattributes marks it.
var extensions = map[string]Syntax{
	".toml": Hash, ".yaml": Hash, ".yml": Hash, ".sh": Hash, ".ps1": Hash, ".py": Hash,
	".conf": Hash, ".lock": Hash, ".ini": Hash, ".cfg": Hash,
	".go": Slash, ".js": Slash, ".ts": Slash,
	".md": HTML, ".html": HTML, ".xml": HTML,
}

// Locks are the third-party lock files, by name, with the tool that writes
// each: exempt from the marker.
var Locks = map[string]string{
	"uv.lock":           "uv",
	"go.sum":            "go",
	"go.work.sum":       "go",
	"package-lock.json": "npm",
	"pnpm-lock.yaml":    "pnpm",
	"yarn.lock":         "yarn",
	"Cargo.lock":        "cargo",
}

// Marker is what a file's marker says.
type Marker struct{ Generator, Source string }

// Line is the marker line in the syntax, without its line end: `Code
// generated by <generator> from <source>. DO NOT EDIT.` in its comment. A
// generator calls it rather than spelling the wording itself.
func Line(generator, source string, s Syntax) string {
	return s.Open + "Code generated by " + generator + " from " + source + ". DO NOT EDIT." + s.Close
}

// Attribute is the generator as .gitattributes' generated-by value: its
// spaces written `:`, as an attribute's value holds none.
func Attribute(generator string) string { return strings.ReplaceAll(generator, " ", ":") }

// SyntaxOf answers the comment syntax of the file at p with the content
// given, false where it has none the rule knows.
func SyntaxOf(p, content string) (Syntax, bool) {
	ext := strings.ToLower(path.Ext(p))
	if s, ok := extensions[ext]; ok {
		return s, true
	}
	if ext == "" && strings.HasPrefix(content, "#!") {
		return Hash, true
	}
	return Syntax{}, false
}

// patterns are each syntax's marker as a regular expression.
var patterns = map[Syntax]*regexp.Regexp{}

func init() {
	for _, s := range []Syntax{Hash, Slash, HTML} {
		patterns[s] = regexp.MustCompile("^" + regexp.QuoteMeta(s.Open) +
			`Code generated by (\S(?:.*?\S)?) from (\S(?:.*?\S)?)\. DO NOT EDIT\.` + regexp.QuoteMeta(s.Close) + "$")
	}
}

// Place answers the index of the line the marker stands on: 0, or the line
// after one the format fixes (`#!`, `<?xml`, Markdown front matter).
func Place(content string, s Syntax) int {
	ls := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
	if strings.HasPrefix(ls[0], "#!") || strings.HasPrefix(ls[0], "<?xml") {
		return 1
	}
	if s == HTML && ls[0] == "---" {
		for i := 1; i < len(ls); i++ {
			if ls[i] == "---" {
				return i + 1
			}
		}
	}
	return 0
}

// MarkerAt answers the marker of content where it stands at its place.
func MarkerAt(content string, s Syntax) (Marker, bool) {
	ls := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
	at := Place(content, s)
	if at >= len(ls) {
		return Marker{}, false
	}
	m := patterns[s].FindStringSubmatch(ls[at])
	if m == nil {
		return Marker{}, false
	}
	return Marker{m[1], m[2]}, true
}

// Mark answers content with its marker at its place; an earlier marker there
// is replaced.
func Mark(content, generator, source string, s Syntax) string {
	ls := strings.Split(content, "\n")
	at := Place(content, s)
	if _, ok := MarkerAt(content, s); ok {
		ls = append(ls[:at], ls[at+1:]...)
	}
	ls = append(ls[:at], append([]string{Line(generator, source, s)}, ls[at:]...)...)
	return strings.Join(ls, "\n")
}

// Generator is one generator as generated.yaml declares it.
type Generator struct {
	Generator, Source string
	Outputs           []string
	Check             []string
	HeldBy            string
	Unchecked         string
	// Line is the generator's line in generated.yaml; OutputLines each output's.
	Line        int
	OutputLines []int
}

// ReadDeclarations reads generated.yaml's content: its generators, or why it
// cannot be read, with its line.
func ReadDeclarations(content string) ([]Generator, int, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal([]byte(content), &doc); err != nil {
		return nil, 1, err
	}
	if len(doc.Content) == 0 {
		return nil, 1, fmt.Errorf("one key, generators, a list of generators")
	}
	top := doc.Content[0]
	if top.Kind != yaml.MappingNode || len(top.Content) != 2 || top.Content[0].Value != "generators" || top.Content[1].Kind != yaml.SequenceNode {
		return nil, top.Line, fmt.Errorf("one key, generators, a list of generators")
	}
	var found []Generator
	seen := map[string]bool{}
	for i, entry := range top.Content[1].Content {
		where := fmt.Sprintf("generator %d", i+1)
		if entry.Kind != yaml.MappingNode {
			return nil, entry.Line, fmt.Errorf("%s is no mapping", where)
		}
		g := Generator{Line: entry.Line}
		var ways []string
		for k := 0; k+1 < len(entry.Content); k += 2 {
			key, value := entry.Content[k], entry.Content[k+1]
			text := func() (string, error) {
				if value.Kind != yaml.ScalarNode || strings.TrimSpace(value.Value) == "" {
					return "", fmt.Errorf("%s: %s is its words", where, key.Value)
				}
				return value.Value, nil
			}
			list := func() ([]string, []int, error) {
				if value.Kind != yaml.SequenceNode {
					return nil, nil, fmt.Errorf("%s: %s is a list", where, key.Value)
				}
				var words []string
				var lines []int
				for _, w := range value.Content {
					if w.Kind != yaml.ScalarNode || w.Value == "" {
						return nil, nil, fmt.Errorf("%s: %s is a list of words", where, key.Value)
					}
					words = append(words, w.Value)
					lines = append(lines, w.Line)
				}
				return words, lines, nil
			}
			var err error
			switch key.Value {
			case "generator":
				g.Generator, err = text()
			case "source":
				g.Source, err = text()
			case "outputs":
				g.Outputs, g.OutputLines, err = list()
			case "check":
				g.Check, _, err = list()
				ways = append(ways, key.Value)
			case "held_by":
				g.HeldBy, err = text()
				ways = append(ways, key.Value)
			case "unchecked":
				g.Unchecked, err = text()
				ways = append(ways, key.Value)
			default:
				err = fmt.Errorf("%s: unknown key %s", where, key.Value)
			}
			if err != nil {
				return nil, key.Line, err
			}
		}
		switch {
		case g.Generator == "" || g.Source == "":
			return nil, entry.Line, fmt.Errorf("%s: generator and source are its words", where)
		case seen[g.Generator]:
			return nil, entry.Line, fmt.Errorf("%s: %s is declared twice; declare each generator once", where, g.Generator)
		case len(g.Outputs) == 0:
			return nil, entry.Line, fmt.Errorf("%s (%s): outputs is a list of the paths it writes", where, g.Generator)
		case len(ways) != 1:
			return nil, entry.Line, fmt.Errorf("%s (%s): name exactly one of check, held_by and unchecked, how a fresh run is compared", where, g.Generator)
		}
		seen[g.Generator] = true
		found = append(found, g)
	}
	return found, 0, nil
}

// Glob is a path glob as a regular expression: `**` across folders, `*` and
// `?` within one.
func Glob(pattern string) *regexp.Regexp {
	var b strings.Builder
	for i := 0; i < len(pattern); {
		switch {
		case strings.HasPrefix(pattern[i:], "**/"):
			b.WriteString("(?:.*/)?")
			i += 3
		case strings.HasPrefix(pattern[i:], "**"):
			b.WriteString(".*")
			i += 2
		case pattern[i] == '*':
			b.WriteString("[^/]*")
			i++
		case pattern[i] == '?':
			b.WriteString("[^/]")
			i++
		default:
			b.WriteString(regexp.QuoteMeta(pattern[i : i+1]))
			i++
		}
	}
	return regexp.MustCompile("^" + b.String() + "$")
}

// attrLine is one .gitattributes line that sets linguist-generated or
// generated-by: its pattern (one without a `/` matches a name at any depth,
// as git's does) and its values.
type attrLine struct {
	pattern *regexp.Regexp
	values  map[string]string
}

func readAttributes(content string) []attrLine {
	var found []attrLine
	for _, l := range lines(content) {
		words := strings.Fields(l)
		if len(words) == 0 || strings.HasPrefix(words[0], "#") {
			continue
		}
		values := map[string]string{}
		for _, w := range words[1:] {
			key, value, _ := strings.Cut(w, "=")
			if value == "" {
				value = "set"
				if strings.HasPrefix(key, "-") {
					value = "unset"
				}
			}
			values[key] = value
		}
		if _, ok := values[linguist]; !ok {
			if _, ok := values[attribute]; !ok {
				continue
			}
		}
		p := strings.TrimPrefix(words[0], "/")
		if !strings.Contains(words[0], "/") {
			p = "**/" + words[0]
		}
		found = append(found, attrLine{Glob(p), values})
	}
	return found
}

// attributesOf answers the generated attributes the lines give p, the last
// line that matches winning.
func attributesOf(p string, ls []attrLine) map[string]string {
	given := map[string]string{}
	for _, l := range ls {
		if l.pattern.MatchString(p) {
			for _, key := range []string{linguist, attribute} {
				if v, ok := l.values[key]; ok {
					given[key] = v
				}
			}
		}
	}
	return given
}

// fixedDir is the folder a glob names before its first wildcard.
func fixedDir(glob string) string {
	if i := strings.IndexAny(glob, "*?"); i >= 0 {
		glob = glob[:i]
	}
	return path.Dir(glob + "x")
}

// generated is the rule over every file of the set: its errors and its
// notices. Declarations are judged where generated.yaml is among the files,
// or where the checker is handed the whole checkout (a managed folder ".");
// a declaration's outputs and its held_by only where they lie in a managed
// folder, since only there does the checker know every file that stands.
func (s *set) generated() []Finding {
	var found []Finding
	var gens []Generator
	known := s.whole
	if f, ok := s.files[Declarations]; ok && f.Held {
		known = true
		var line int
		var err error
		if gens, line, err = ReadDeclarations(f.Content); err != nil {
			return []Finding{{Path: Declarations, Line: line, Col: 1, Rule: RuleGenerated,
				Message: fmt.Sprintf("%s cannot be read: %v", Declarations, err)}}
		}
	}
	var attrs []attrLine
	if f, ok := s.files[Attributes]; ok && f.Held {
		attrs = readAttributes(f.Content)
	}
	globs := make([][]*regexp.Regexp, len(gens))
	for i, g := range gens {
		for _, o := range g.Outputs {
			globs[i] = append(globs[i], Glob(o))
		}
	}
	for i, g := range gens {
		for j, o := range g.Outputs {
			if !s.inside(fixedDir(o)) {
				continue
			}
			matched := false
			for _, p := range s.paths {
				if matched = globs[i][j].MatchString(p); matched {
					break
				}
			}
			if !matched {
				found = append(found, Finding{Path: Declarations, Line: g.OutputLines[j], Col: 1, Rule: RuleGenerated,
					Message: fmt.Sprintf("%s declares %s, which matches no file; remove it, or run the generator and commit what it writes", g.Generator, o)})
			}
		}
		if g.HeldBy != "" && s.inside(g.HeldBy) && !s.stands(g.HeldBy) {
			found = append(found, Finding{Path: Declarations, Line: g.Line, Col: 1, Rule: RuleGenerated,
				Message: fmt.Sprintf("%s is held by %s, which does not exist; name the test or workflow that reruns it", g.Generator, g.HeldBy)})
		}
	}
	for _, p := range s.paths {
		f := s.files[p]
		var owners []Generator
		for i, g := range gens {
			for _, re := range globs[i] {
				if re.MatchString(p) {
					owners = append(owners, g)
					break
				}
			}
		}
		found = append(found, s.generatedFile(f, owners, known, attrs)...)
	}
	return found
}

// generatedFile is the rule on one file: owners are the generators that
// declare it, known whether the declarations are known.
func (s *set) generatedFile(f File, owners []Generator, known bool, attrs []attrLine) []Finding {
	at := func(line int, notice bool, format string, a ...any) Finding {
		sev := ""
		if notice {
			sev = SeverityNotice
		}
		return Finding{Path: f.Path, Line: line, Col: 1, Rule: RuleGenerated, Severity: sev, Message: fmt.Sprintf(format, a...)}
	}
	if tool, ok := Locks[path.Base(f.Path)]; ok {
		if len(owners) > 0 {
			return []Finding{at(1, false, "%s's lock file, exempt from the marker; remove it from %s", tool, Declarations)}
		}
		return []Finding{at(1, true, "generated by %s; edit what it locks, then run it", tool)}
	}
	syntax, commented := SyntaxOf(f.Path, f.Content)
	if commented && !f.Held {
		return nil // its marker cannot be read
	}
	var seen Marker
	marked := false
	line := 1
	if commented {
		seen, marked = MarkerAt(f.Content, syntax)
		line = Place(f.Content, syntax) + 1
	}
	given := attributesOf(f.Path, attrs)
	var found []Finding
	switch {
	case len(owners) > 1:
		var names []string
		for _, g := range owners {
			names = append(names, g.Generator)
		}
		found = append(found, at(line, false, "declared by %s; one generator writes a file, so declare it once in %s", strings.Join(names, " and "), Declarations))
	case len(owners) == 1 && !commented:
		want := Attribute(owners[0].Generator)
		if (given[linguist] != "set" && given[linguist] != "true") || given[attribute] != want {
			found = append(found, at(1, false, "generated by %s, in a format without comments, so %s marks it: add `%s %s %s=%s` (or a pattern that covers it)",
				owners[0].Generator, Attributes, f.Path, linguist, attribute, want))
		}
	case len(owners) == 1 && !marked:
		found = append(found, at(line, false, "generated by %s but lacks its marker `%s`; run %s, which writes it, and edit %s instead of the file",
			owners[0].Generator, Line(owners[0].Generator, owners[0].Source, syntax), owners[0].Generator, owners[0].Source))
	case len(owners) == 1 && seen.Generator != owners[0].Generator:
		found = append(found, at(line, false, "its marker names %s, but %s declares it %s's output; run %s, or declare the file under %s",
			seen.Generator, Declarations, owners[0].Generator, owners[0].Generator, seen.Generator))
	case len(owners) == 0 && known && marked:
		found = append(found, at(line, false, "marked as generated by %s, which %s does not declare it of; declare it among %s's outputs, or remove the marker from a hand-written file",
			seen.Generator, Declarations, seen.Generator))
	case len(owners) == 0 && known && given[attribute] != "":
		found = append(found, at(1, false, "%s marks it as generated by %s, which %s does not declare it of; declare it, or remove the attribute",
			Attributes, given[attribute], Declarations))
	}
	switch {
	case marked:
		found = append(found, at(line, true, "generated by %s from %s; edit %s", seen.Generator, seen.Source, seen.Source))
	case len(owners) > 0:
		found = append(found, at(line, true, "generated by %s from %s; edit %s", owners[0].Generator, owners[0].Source, owners[0].Source))
	case given[attribute] != "":
		found = append(found, at(1, true, "generated by %s", strings.ReplaceAll(given[attribute], ":", " ")))
	}
	return found
}

// inside says whether p lies where the checker knows every file: the whole
// checkout, or a managed folder.
func (s *set) inside(p string) bool {
	return s.whole || s.managed(path.Clean(p))
}
